class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        @lru_cache(None)
        def dp(v: int) -> int:
            if v <= y:
                return y - v

            ans = v - y

            ans = min(ans, v % 5 + 1 + dp(v // 5))
            ans = min(ans, 5 - v % 5 + 1 + dp(v // 5 + 1))

            ans = min(ans, v % 11 + 1 + dp(v // 11))
            ans = min(ans, 11 - v % 11 + 1 + dp(v // 11 + 1))

