class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        MOD = 10**9 + 7
        mask = (1 << n) - 1

        A = a & ~mask
        B = b & ~mask

        for i in range(n - 1, -1, -1):
            ai = (a >> i) & 1
            bi = (b >> i) & 1

            if ai == bi:
                A |= 1 << i
                B |= 1 << i
            else:
                if A > B:
                    B |= 1 << i
                else:
                    A |= 1 << i

        return (A % MOD) * (B % MOD) % MOD
