from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]
    A = data[1:1 + N]

    B = [A[i] - i for i in range(N)]
    C = [A[i] + i for i in range(N)]

    def feasible(k):
        if 2 * k - 1 > N:
            return False

        # minCStart[s] = min(C[s], C[s+1], ..., C[s+k-1])
        m = N - k + 1
        minCStart = [0] * m
        dq = deque()

        for idx in range(N):
            val = C[idx]
            while dq and C[dq[-1]] >= val:
                dq.pop()
            dq.append(idx)

            if dq[0] <= idx - k:
                dq.popleft()

            if idx >= k - 1:
                start = idx - k + 1
                minCStart[start] = C[dq[0]]

        dq.clear()

        # end is the center index of the pyramid.
        for end in range(N - k + 1):
            val = B[end]
            while dq and B[dq[-1]] >= val:
                dq.pop()
            dq.append(end)

            if dq[0] <= end - k:
                dq.popleft()

            if end >= k - 1:
                # Left half covers [end-k+1, end]
                # Right half covers [end, end+k-1]
                if B[dq[0]] >= k - end and minCStart[end] >= end + k:
                    return True

        return False

    low = 0
    high = (N + 1) // 2 + 1

    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(low)


if __name__ == "__main__":
    main()
