class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        def can(t: int) -> bool:
            last = [-1] * n
            for i in range(t):
                last[changeIndices[i] - 1] = i

            if any(pos == -1 for pos in last):
                return False

            free = 0
            for i in range(t):
                idx = changeIndices[i] - 1
                if last[idx] == i:
                    if free < nums[idx]:
                        return False
                    free -= nums[idx]
                else:
                    free += 1

            return True

        ans = -1
        left, right = 1, m

        while left <= right:
            mid = (left + right) // 2
            if can(mid):
                ans = mid
                right = mid - 1
            else:
                left = mid + 1

        return ans
