def main():
    input = sys.stdin.buffer.readline
    N, M = map(int, input().split())

    reverse_edges = [[] for _ in range(N + 1)]

    for _ in range(M):
        l, d, k, c, A, B = map(int, input().split())
        reverse_edges[B].append((l, d, k, c, A))

    INF = 10**30
    dp = [-1] * (N + 1)
    dp[N] = INF

    pq = [(-INF, N)]

    while pq:
        neg_time, station = heapq.heappop(pq)
        time = -neg_time

        if time != dp[station]:
            continue

        for l, d, k, c, A in reverse_edges[station]:
            limit = time - c

            if limit < l:
                continue

            j = (limit - l) // d
            if j >= k:
                j = k - 1

            departure_time = l + j * d

            if departure_time > dp[A]:
                dp[A] = departure_time
                heapq.heappush(pq, (-departure_time, A))

    ans = []
    for i in range(1, N):
        if dp[i] < 0:
            ans.append("Unreachable")
        else:
            ans.append(str(dp[i]))

    sys.stdout.write("\n".join(ans))


